  .footer-grid { grid-template-columns: 1fr; }
  .section-head { flex-direction: column; align-items: flex-start; }
  .section { margin-top: 64px; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .tab, .icon-btn, .wishlist-btn, .field-row button { border: 1px solid CanvasText; }
  .btn-primary, .quick-add, .tab[aria-selected="true"] { background: ButtonText; color: ButtonFace; }
  .deal-card::after, .cat-card::after { background: none; }
  .deal-card, .deal-body { color: CanvasText; background: Canvas; }
}
