/* ========== Design tokens ========== */
:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --surface-alt: #f3f1ec;
  --ink: #161513;
  --ink-2: #3a3833;
  --muted: #6b6862;
  --line: #e6e3dc;
  --accent: #1f1d1a;
  --accent-ink: #fafaf7;
  --sale: #b3361f;
  --focus: #2864ff;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20,18,15,.04), 0 2px 6px rgba(20,18,15,.04);
  --shadow-md: 0 6px 24px rgba(20,18,15,.08);
  --maxw: 1240px;
  --pad: clamp(16px, 4vw, 40px);
  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-display: "Fraunces", "Playfair Display", Georgia, "Times New Roman", serif;
}

/* ========== Reset ========== */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img, svg { display: block; max-width: 100%; }
button { font: inherit; color: inherit; }
a { color: inherit; }

/* ========== Skip link ========== */
.skip-link {
  position: absolute;
  left: 12px;
  top: -100px;
  background: var(--ink);
  color: var(--accent-ink);
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 200;
  transition: top .15s ease;
}
.skip-link:focus { top: 12px; }

/* ========== Focus ========== */
:focus { outline: none; }
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ========== Layout helpers ========== */
.container {
  max-width: var(--maxw);
  margin-inline: auto;
  padding-inline: var(--pad);
}

/* ========== Announcement bar ========== */
.announcement {
  background: var(--ink);
  color: var(--accent-ink);
  font-size: 13px;
  letter-spacing: .02em;
  text-align: center;
  padding: 10px 16px;
}
.announcement strong { font-weight: 600; }

/* ========== Header ========== */
.site-header {
  position: sticky;
  top: 0;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(150%) blur(10px);
  -webkit-backdrop-filter: saturate(150%) blur(10px);
  border-bottom: 1px solid var(--line);
  z-index: 50;
}
.header-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding-block: 16px;
}
.brand {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 22px;
  letter-spacing: -0.01em;
  text-decoration: none;
  color: var(--ink);
}
.brand span { font-style: italic; }

.primary-nav ul {
  display: flex;
  gap: 28px;
  margin: 0;
  padding: 0;
  list-style: none;
  justify-content: center;
}
.primary-nav a {
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}
.primary-nav a:hover { color: var(--ink); border-bottom-color: var(--ink); }
.primary-nav a[aria-current="page"] { color: var(--ink); border-bottom-color: var(--ink); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--surface-alt); }
.icon-btn svg { width: 20px; height: 20px; stroke: currentColor; fill: none; stroke-width: 1.6; }
.cart-count {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  background: var(--sale);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.menu-toggle { display: none; }

/* ========== Hero ========== */
.hero {
  position: relative;
  margin-top: 24px;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(20px, 4vw, 56px);
  align-items: stretch;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 24px;
  overflow: hidden;
}
.hero-copy {
  padding: clamp(28px, 5vw, 64px);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.eyebrow {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 18px;
}
.hero h1 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(36px, 5.4vw, 64px);
  line-height: 1.04;
  letter-spacing: -0.02em;
  margin: 0 0 20px;
}
.hero h1 em { font-style: italic; color: var(--ink-2); }
.hero p {
  font-size: 17px;
  color: var(--ink-2);
  max-width: 46ch;
  margin: 0 0 28px;
}
.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 22px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: .01em;
  text-decoration: none;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform .08s ease, background .15s ease, color .15s ease, border-color .15s ease;
  min-height: 44px;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--ink);
  color: var(--accent-ink);
  border-color: var(--ink);
}
.btn-primary:hover { background: #000; }
.btn-secondary {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-secondary:hover { background: var(--ink); color: var(--accent-ink); }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line);
}
.btn-ghost:hover { background: var(--surface-alt); }

.hero-media {
  position: relative;
  background: var(--surface-alt);
  min-height: 360px;
}
.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.hero-badge {
  position: absolute;
  top: 18px;
  right: 18px;
  background: rgba(255,255,255,.92);
  color: var(--ink);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
}

/* ========== Categories strip ========== */
.categories {
  margin-top: 56px;
}
.cat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.cat-card {
  position: relative;
  display: block;
  text-decoration: none;
  color: var(--ink);
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 4/5;
  background: var(--surface-alt);
  isolation: isolate;
}
.cat-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.cat-card:hover img { transform: scale(1.04); }
.cat-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.55), rgba(0,0,0,0) 55%);
}
.cat-label {
  position: absolute;
  left: 16px;
  bottom: 14px;
  z-index: 2;
  color: #fff;
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.cat-label small {
  display: block;
  font-family: var(--font-sans);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: .06em;
  text-transform: uppercase;
  opacity: .85;
  margin-top: 2px;
}

/* ========== Section heading ========== */
.section { margin-top: 88px; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 40px);
  letter-spacing: -0.015em;
  margin: 0;
}
.section-head p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 15px;
}
.section-head a.link {
  color: var(--ink);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
  white-space: nowrap;
}

/* ========== Tabs ========== */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}
.tab {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink-2);
  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
}
.tab[aria-selected="true"] {
  background: var(--ink);
  color: var(--accent-ink);
  border-color: var(--ink);
}
.tab:hover:not([aria-selected="true"]) { background: var(--surface-alt); }

/* ========== Product grid ========== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px 20px;
}
.product-card {
  background: transparent;
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
}
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--surface-alt);
  border-radius: var(--radius);
  overflow: hidden;
}
.product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.product-card:hover .product-media img { transform: scale(1.03); }
.tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--surface);
  color: var(--ink);
  padding: 5px 10px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  border-radius: 999px;
}
.tag.tag-sale { background: var(--sale); color: #fff; }
.tag.tag-new { background: var(--ink); color: #fff; }

.wishlist-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 36px;
  height: 36px;
  background: rgba(255,255,255,.9);
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.wishlist-btn svg { width: 16px; height: 16px; stroke: var(--ink); fill: none; stroke-width: 1.8; }
.wishlist-btn[aria-pressed="true"] svg { fill: var(--sale); stroke: var(--sale); }

.quick-add {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  background: var(--ink);
  color: var(--accent-ink);
  border: none;
  border-radius: 999px;
  padding: 11px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .18s ease, transform .18s ease;
  min-height: 40px;
}
.product-card:hover .quick-add,
.product-card:focus-within .quick-add { opacity: 1; transform: translateY(0); }
@media (hover: none) {
  .quick-add { opacity: 1; transform: none; }
}

.product-info {
  padding: 14px 4px 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.product-title {
  font-size: 15px;
  font-weight: 500;
  margin: 0;
  color: var(--ink);
}
.product-title a { text-decoration: none; }
.product-title a:hover { text-decoration: underline; text-underline-offset: 3px; }
.product-meta {
  font-size: 13px;
  color: var(--muted);
  margin: 0;
}
.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 4px;
}
.price-current { font-size: 15px; font-weight: 600; color: var(--ink); }
.price-was { font-size: 13px; color: var(--muted); text-decoration: line-through; }
.swatches {
  display: flex;
  gap: 6px;
  margin-top: 6px;
}
.swatch {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1px solid var(--line);
  display: inline-block;
}

/* ========== Deals (split feature) ========== */
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 20px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  min-height: 360px;
  color: #fff;
  isolation: isolate;
  display: flex;
  align-items: end;
  background: var(--ink);
}
.deal-card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
}
.deal-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top right, rgba(0,0,0,.65), rgba(0,0,0,.1) 60%);
  z-index: -1;
}
.deal-body { padding: clamp(22px, 3vw, 36px); max-width: 520px; }
.deal-body .eyebrow { color: rgba(255,255,255,.85); margin-bottom: 10px; }
.deal-body h3 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(24px, 2.6vw, 34px);
  line-height: 1.1;
  margin: 0 0 10px;
  letter-spacing: -0.01em;
}
.deal-body p { margin: 0 0 18px; opacity: .9; font-size: 15px; }
.deal-body .btn-light {
  background: #fff;
  color: var(--ink);
  border-color: #fff;
}
.deal-body .btn-light:hover { background: var(--surface-alt); }

/* Countdown */
.countdown {
  display: flex;
  gap: 8px;
  margin: 8px 0 18px;
}
.countdown-item {
  background: rgba(255,255,255,.16);
  border: 1px solid rgba(255,255,255,.24);
  border-radius: 10px;
  padding: 8px 10px;
  min-width: 56px;
  text-align: center;
  backdrop-filter: blur(4px);
}
.countdown-num {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  display: block;
  line-height: 1;
}
.countdown-label {
  font-size: 10px;
  letter-spacing: .12em;
  text-transform: uppercase;
  opacity: .8;
  margin-top: 4px;
  display: block;
}

/* ========== Editorial ========== */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: var(--ink);
  border-radius: var(--radius);
}
.article-media {
  aspect-ratio: 4/3;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface-alt);
  margin-bottom: 16px;
}
.article-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.article-card:hover .article-media img { transform: scale(1.03); }
.article-meta {
  font-size: 12px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 8px;
}
.article-title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 22px;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin: 0 0 8px;
}
.article-card:hover .article-title { text-decoration: underline; text-underline-offset: 4px; }
.article-excerpt {
  margin: 0;
  font-size: 14px;
  color: var(--muted);
}

/* ========== Value props ========== */
.value-props {
  margin-top: 88px;
  border-block: 1px solid var(--line);
  padding-block: 32px;
}
.vp-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.vp {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.vp svg { width: 24px; height: 24px; stroke: var(--ink); fill: none; stroke-width: 1.5; flex: none; margin-top: 2px; }
.vp h4 { margin: 0 0 4px; font-size: 14px; font-weight: 600; }
.vp p { margin: 0; font-size: 13px; color: var(--muted); }

/* ========== Newsletter ========== */
.newsletter {
  margin-top: 88px;
  background: var(--ink);
  color: var(--accent-ink);
  border-radius: 24px;
  padding: clamp(36px, 6vw, 72px);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 40px);
  letter-spacing: -0.015em;
  margin: 0 0 12px;
}
.newsletter p { margin: 0; opacity: .85; font-size: 15px; max-width: 50ch; }
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.field-row {
  display: flex;
  gap: 8px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 999px;
  padding: 4px;
}
.field-row:focus-within {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.field-row input {
  flex: 1;
  background: transparent;
  border: none;
  color: #fff;
  padding: 12px 18px;
  font-size: 15px;
  min-width: 0;
}
.field-row input:focus { outline: none; }
.field-row input::placeholder { color: rgba(255,255,255,.6); }
.field-row button {
  background: #fff;
  color: var(--ink);
  border: none;
  border-radius: 999px;
  padding: 0 22px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  min-height: 44px;
}
.field-row button:hover { background: var(--surface-alt); }
.newsletter-help {
  font-size: 12px;
  opacity: .7;
  margin: 0;
}
.newsletter-status {
  font-size: 14px;
  margin: 4px 0 0;
  min-height: 1.2em;
}

/* ========== Footer ========== */
.site-footer {
  margin-top: 80px;
  padding-block: 56px 32px;
  border-top: 1px solid var(--line);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 40px;
}
.footer-brand p {
  color: var(--muted);
  font-size: 14px;
  margin: 12px 0 16px;
  max-width: 36ch;
}
.social {
  display: flex;
  gap: 8px;
}
.footer-col h5 {
  margin: 0 0 14px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.footer-col a {
  text-decoration: none;
  color: var(--ink-2);
  font-size: 14px;
}
.footer-col a:hover { color: var(--ink); text-decoration: underline; text-underline-offset: 3px; }
.footer-bottom {
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  color: var(--muted);
  font-size: 13px;
}

/* ========== sr-only ========== */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* ========== Responsive ========== */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .vp-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 820px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-media { min-height: 300px; aspect-ratio: 4/3; }
  .deals-grid { grid-template-columns: 1fr; }
  .newsletter { grid-template-columns: 1fr; }
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .primary-nav { display: none; }
  .primary-nav.is-open {
    display: block;
    position: absolute;
    left: 0; right: 0; top: 100%;
    background: var(--surface);
