:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --surface-alt: #f3f1ec;
  --ink: #161513;
  --ink-2: #3a3833;
  --muted: #6b6862;
  --line: #e6e3dc;
  --accent: #1f1d1a;
  --accent-ink: #fafaf7;
  --sale: #b3361f;
  --focus: #2864ff;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20,18,15,.04), 0 2px 6px rgba(20,18,15,.04);
  --shadow-md: 0 6px 24px rgba(20,18,15,.08);
  --maxw: 1240px;
  --pad: clamp(16px, 4vw, 40px);
  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-display: "Fraunces", "Playfair Display", Georgia, "Times New Roman", serif;
}

/* ========== Reset ========== */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img, svg { display: block; max-width: 100%; }
button { font: inherit; color: inherit; }
a { color: inherit; }

/* ========== Skip link ========== */
.skip-link {
  position: absolute;
  left: 12px;
  top: -100px;
  background: var(--ink);
  color: var(--accent-ink);
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 200;
  transition: top .15s ease;
}
.skip-link:focus { top: 12px; }

/* ========== Focus ========== */
:focus { outline: none; }
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ========== Layout helpers ========== */
.container {
  max-width: var(--maxw);
  margin-inline: auto;
  padding-inline: var(--pad);
}

/* ========== Announcement bar ========== */
.announcement {
  background: var(--ink);
  color: var(--accent-ink);
  font-size: 13px;
  letter-spacing: .02em;
  text-align: center;
  padding: 10px 16px;
}
.announcement strong { font-weight: 600; }

/* ========== Header ========== */
.site-header {
  position: sticky;
  top: 0;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(150%) blur(10px);
  -webkit-backdrop-filter: saturate(150%) blur(10px);
  border-bottom: 1px solid var(--line);
  z-index: 50;
}
.header-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding-block: 16px;
}
.brand {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 22px;
  letter-spacing: -0.01em;
  text-decoration: none;
  color: var(--ink);
}
.brand span { font-style: italic; }

.primary-nav ul {
  display: flex;
  gap: 28px;
  margin: 0;
  padding: 0;
  list-style: none;
  justify-content: center;
}
.primary-nav a {
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}
.primary-nav a:hover { color: var(--ink); border-bottom-color: var(--ink); }
.primary-nav a[aria-current="page"] { color: var(--ink); border-bottom-color: var(--ink); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--surface-alt); }
.icon-btn svg { width: 20px; height: 20px; stroke: currentColor; fill: none; stroke-width: 1.6; }
.cart-count {
  position: absolute;
