}
.btn-ghost:hover { background: var(--surface-alt); }

.hero-media {
  position: relative;
  background: var(--surface-alt);
  min-height: 360px;
}
.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.hero-badge {
  position: absolute;
  top: 18px;
  right: 18px;
  background: rgba(255,255,255,.92);
  color: var(--ink);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
