  font-size: clamp(28px, 3.6vw, 40px);
  letter-spacing: -0.015em;
  margin: 0;
}
.section-head p {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 15px;
}
.section-head a.link {
  color: var(--ink);
