  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
}
.tab[aria-selected="true"] {
  background: var(--ink);
  color: var(--accent-ink);
  border-color: var(--ink);
}
.tab:hover:not([aria-selected="true"]) { background: var(--surface-alt); }

/* ========== Product grid ========== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px 20px;
}
.product-card {
  background: transparent;
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
}
.product-media {
  position: relative;
  aspect-ratio: 4/5;
  background: var(--surface-alt);
  border-radius: var(--radius);
  overflow: hidden;
}
.product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.product-card:hover .product-media img { transform: scale(1.03); }
.tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--surface);
  color: var(--ink);
  padding: 5px 10px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  border-radius: 999px;
}
.tag.tag-sale { background: var(--sale); color: #fff; }
.tag.tag-new { background: var(--ink); color: #fff; }

.wishlist-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 36px;
  height: 36px;
  background: rgba(255,255,255,.9);
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.wishlist-btn svg { width: 16px; height: 16px; stroke: var(--ink); fill: none; stroke-width: 1.8; }
.wishlist-btn[aria-pressed="true"] svg { fill: var(--sale); stroke: var(--sale); }

.quick-add {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  background: var(--ink);
  color: var(--accent-ink);
  border: none;
  border-radius: 999px;
  padding: 11px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .18s ease, transform .18s ease;
  min-height: 40px;
}
.product-card:hover .quick-add,
.product-card:focus-within .quick-add { opacity: 1; transform: translateY(0); }
@media (hover: none) {
  .quick-add { opacity: 1; transform: none; }
}

.product-info {
  padding: 14px 4px 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.product-title {
  font-size: 15px;
  font-weight: 500;
  margin: 0;
  color: var(--ink);
}
.product-title a { text-decoration: none; }
.product-title a:hover { text-decoration: underline; text-underline-offset: 3px; }
.product-meta {
  font-size: 13px;
  color: var(--muted);
  margin: 0;
}
.product-price {
