            Quiet essentials, <em>built to last.</em>
          </h1>
          <p>
            Considered pieces in natural fibers — designed in our Copenhagen
            studio and made in small batches by craftspeople we know by name.
          </p>
          <div className="hero-cta">
            <a href="#shop" className="btn btn-primary">Shop the collection</a>
            <a href="#story" className="btn btn-ghost">Our story</a>
          </div>
        </div>
        <div className="hero-media">
          <span className="hero-badge">New Drop</span>
          <img
            src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=1200&q=70"
            alt="A model wearing a cream wool coat over a charcoal turtleneck, photographed against a soft beige backdrop."
            loading="eager"
          />
        </div>
      </div>
    </section>
  );
}

function CategoryCard({ label, count, img }) {
  return (
    <a href={`#${label.toLowerCase()}`} className="cat-card" aria-label={`${label} category, ${count}`}>
      <img src={img} alt="" loading="lazy" />
      <span className="cat-label" aria-hidden="true">
        {label}
        <small>{count}</small>
      </span>
    </a>
  );
}

function Categories() {
  return (
    <section className="categories container" aria-labelledby="cat-heading">
      <h2 id="cat-heading" className="sr-only">Shop by category</h2>
      <div className="cat-grid">
        {CATEGORIES.map(c => <CategoryCard key={c.label} {...c} />)}
      </div>
    </section>
  );
}

function ProductCard({ product, onAdd, onWishlist, wished }) {
  const fmt = (n) => `$${n.toFixed(0)}`;
  const titleId = `pt-${product.id}`;
  return (
    <article className="product-card" aria-labelledby={titleId}>
      <div className="product-media">
        {product.tag && (
          <span className={`tag${product.tag === "Sale" ? " tag-sale" : product.tag === "New" ? " tag-new" : ""}`}>
            {product.tag}
          </span>
        )}
        <button
          type="button"
          className="wishlist-btn"
          aria-pressed={wished}
          aria-label={`${wished ? "Remove from" : "Add to"} wishlist: ${product.name}`}
          onClick={() => onWishlist(product.id)}
        >
          <Icon name="heart" />
        </button>
        <img src={product.img} alt={`${product.name} in ${product.category.toLowerCase()}`} loading="lazy" />
        <button type="button" className="quick-add" onClick={() => onAdd(product)}>
          Quick add
        </button>
      </div>
      <div className="product-info">
        <p className="product-meta">{product.category}</p>
        <h3 className="product-title" id={titleId}>
          <a href={`#product-${product.id}`}>{product.name}</a>
        </h3>
        <div className="product-price">
          <span className="price-current">
            <span className="sr-only">Price: </span>{fmt(product.price)}
          </span>
          {product.was && (
            <span className="price-was">
              <span className="sr-only">Was </span>{fmt(product.was)}
            </span>
          )}
        </div>
        {product.swatches?.length > 0 && (
          <div className="swatches" aria-label={`${product.swatches.length} colors available`}>
            {product.swatches.map((c, i) => (
              <span key={i} className="swatch" style={{ background: c }} aria-hidden="true" />
            ))}
          </div>
        )}
      </div>
    </article>
  );
}

function FeaturedProducts({ onAdd }) {
  const tabs = Object.keys(PRODUCTS);
  const [active, setActive] = useState(tabs[0]);
  const [wishlist, setWishlist] = useState(new Set());

  const toggleWish = (id) => {
    setWishlist(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  return (
    <section className="section container" aria-labelledby="featured-heading">
      <div className="section-head">
        <div>
          <h2 id="featured-heading">Featured products</h2>
          <p>Hand-picked from our latest collection.</p>
        </div>
        <a href="#all" className="link">View all</a>
      </div>

      <div className="tabs" role="tablist" aria-label="Featured product categories">
        {tabs.map(t => (
          <button
            key={t}
            role="tab"
            type="button"
            className="tab"
            aria-selected={active === t}
            aria-controls={`tab-panel-${t.replace(/\s+/g,'-')}`}
            id={`tab-${t.replace(/\s+/g,'-')}`}
            tabIndex={active === t ? 0 : -1}
            onClick={() => setActive(t)}
          >
            {t}
          </button>
        ))}
      </div>

      {tabs.map(t => (
        <div
          key={t}
          role="tabpanel"
          id={`tab-panel-${t.replace(/\s+/g,'-')}`}
          aria-labelledby={`tab-${t.replace(/\s+/g,'-')}`}
          hidden={active !== t}
        >
          <div className="product-grid">
            {PRODUCTS[t].map(p => (
              <ProductCard
                key={p.id}
                product={p}
                onAdd={onAdd}
                onWishlist={toggleWish}
                wished={wishlist.has(p.id)}
              />
            ))}
          </div>
        </div>
      ))}
    </section>
  );
}

function Countdown({ targetDate }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, targetDate - now);
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff / 3600000) % 24);
  const m = Math.floor((diff / 60000) % 60);
  const s = Math.floor((diff / 1000) % 60);
  const items = [
    { n: d, l: "Days" }, { n: h, l: "Hrs" }, { n: m, l: "Min" }, { n: s, l: "Sec" }
  ];
  const label = `Sale ends in ${d} days, ${h} hours, ${m} minutes`;
  return (
    <div className="countdown" role="timer" aria-live="off" aria-label={label}>
      {items.map(it => (
        <div className="countdown-item" key={it.l} aria-hidden="true">
          <span className="countdown-num">{String(it.n).padStart(2,"0")}</span>
          <span className="countdown-label">{it.l}</span>
        </div>
      ))}
    </div>
  );
}

function Deals() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 53, []);
  return (
    <section className="section container" aria-labelledby="deals-heading">
      <div className="section-head">
        <div>
          <h2 id="deals-heading">This week's deals</h2>
          <p>Limited drops, clearly priced.</p>
        </div>
        <a href="#sale" className="link">Shop sale</a>
      </div>

      <div className="deals-grid">
        <article className="deal-card">
          <img
            src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1400&q=70"
            alt=""
            loading="lazy"
          />
          <div className="deal-body">
            <span className="eyebrow">Member event · Up to 30% off</span>
            <h3>The autumn outerwear edit</h3>
            <Countdown targetDate={target} />
            <p>Coats, jackets, and overshirts at members-only prices. Sign in to shop.</p>
            <a href="#deal" className="btn btn-light">Shop the edit</a>
          </div>
        </article>

        <article className="deal-card">
          <img
            src="https://images.unsplash.com/photo-1521334884684-d80222895322?auto=format&fit=crop&w=1000&q=70"
            alt=""
            loading="lazy"
          />
          <div className="deal-body">
            <span className="eyebrow">Bundle &amp; save</span>
            <h3>Two knits, $50 off</h3>
            <p>Mix and match any two sweaters from the merino collection.</p>
            <a href="#bundle" className="btn btn-light">Build your bundle</a>
          </div>
        </article>
      </div>
    </section>
  );
}

function Editorial() {
  return (
    <section className="section container" aria-labelledby="journal-heading">
      <div className="section-head">
        <div>
          <h2 id="journal-heading">From the journal</h2>
          <p>Stories on craft, design, and the people behind the pieces.</p>
        </div>
        <a href="#journal" className="link">Read all stories</a>
      </div>
      <div className="editorial-grid">
        {ARTICLES.map((a, i) => (
          <a key={i} href={`#article-${i}`} className="article-card">
            <div className="article-media">
              <img src={a.img} alt="" loading="lazy" />
            </div>
            <p className="article-meta">{a.tag}</p>
            <h3 className="article-title">{a.title}</h3>
            <p className="article-excerpt">{a.excerpt}</p>
          </a>
        ))}
      </div>
    </section>
  );
}

function ValueProps() {
  const items = [
    { icon: "truck", title: "Carbon-neutral shipping", body: "Free over $120, worldwide." },
    { icon: "return", title: "60-day returns", body: "No-questions exchanges and refunds." },
    { icon: "leaf", title: "Responsibly made", body: "Traceable fibers, fair-wage partners." },
    { icon: "lock", title: "Secure checkout", body: "All major payment methods accepted." },
  ];
  return (
    <section className="value-props" aria-label="Customer benefits">
      <div className="container vp-grid">
        {items.map(it => (
          <div className="vp" key={it.title}>
            <Icon name={it.icon} />
            <div>
              <h4>{it.title}</h4>
              <p>{it.body}</p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("");
  const id = useId();
  const onSubmit = (e) => {
    e.preventDefault();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setStatus("Please enter a valid email address.");
      return;
    }
    setStatus(`Thanks — we'll send your 10% off code to ${email}.`);
    setEmail("");
  };
  return (
    <section className="newsletter container" aria-labelledby="news-heading">
      <div>
        <h2 id="news-heading">Join the list, get 10% off</h2>
        <p>Early access to drops, journal stories, and the occasional studio note. No spam, ever.</p>
      </div>
      <form className="newsletter-form" onSubmit={onSubmit} noValidate>
        <label htmlFor={`${id}-email`} className="sr-only">Email address</label>
        <div className="field-row">
          <input
            id={`${id}-email`}
            type="email"
            inputMode="email"
            autoComplete="email"
            required
            placeholder="you@domain.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            aria-describedby={`${id}-help ${id}-status`}
          />
          <button type="submit">Subscribe</button>
        </div>
        <p className="newsletter-help" id={`${id}-help`}>By subscribing you agree to our privacy policy.</p>
        <p className="newsletter-status" id={`${id}-status`} role="status" aria-live="polite">{status}</p>
      </form>
    </section>
  );
}

function Footer() {
  const cols = [
    { title: "Shop", links: ["New arrivals", "Bestsellers", "Outerwear", "Knitwear", "Footwear", "Sale"] },
    { title: "Help", links: ["Contact us", "Shipping", "Returns", "Size guide", "Care guide"] },
    { title: "Company", links: ["Our story", "Sustainability", "Stores", "Press", "Careers"] },
  ];
  return (
    <footer className="site-footer">
      <div className="container">
        <div className="footer-grid">
          <div className="footer-brand">
            <a href="#" className="brand">Maren<span>&amp;Co</span></a>
            <p>Considered, long-lasting essentials made in small batches.</p>
            <div className="social">
              <a href="#instagram" className="icon-btn" aria-label="Maren &amp; Co on Instagram"><Icon name="instagram" /></a>
              <a href="#pinterest" className="icon-btn" aria-label="Maren &amp; Co on Pinterest"><Icon name="pinterest" /></a>
              <a href="#twitter" className="icon-btn" aria-label="Maren &amp; Co on Twitter"><Icon name="twitter" /></a>
            </div>
          </div>
          {cols.map(c => (
            <div className="footer-col" key={c.title}>
              <h5>{c.title}</h5>
              <ul>
                {c.links.map(l => <li key={l}><a href={`#${l.toLowerCase().replace(/\s+/g,'-')}`}>{l}</a></li>)}
              </ul>
            </div>
          ))}
        </div>
        <div className="footer-bottom">
          <span>© {new Date().getFullYear()} Maren &amp; Co. All rights reserved.</span>
          <span>Copenhagen · New York · Tokyo</span>
        </div>
      </div>
    </footer>
  );
}

/* ============ App ============ */
function App() {
  const [cart, setCart] = useState([]);
  const [toast, setToast] = useState("");

  const addToCart = (product) => {
    setCart(c => [...c, product]);
    setToast(`${product.name} added to bag.`);
    setTimeout(() => setToast(""), 3000);
  };

  return (
    <>
      <a href="#main" className="skip-link">Skip to main content</a>
      <AnnouncementBar />
      <Header cartCount={cart.length} />
      <main id="main">
        <Hero />
        <Categories />
        <FeaturedProducts onAdd={addToCart} />
        <Deals />
        <Editorial />
        <ValueProps />
        <Newsletter />
      </main>
      <Footer />
      <div role="status" aria-live="polite" className="sr-only">{toast}</div>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
