/* React-style component architecture rendered to a single HTML page.
   Uses React 18 + Babel (in-browser) for clarity. */

const { useState, useEffect, useMemo, useRef, useId } = React;

/* ============ Data ============ */
const NAV_ITEMS = [
  { label: "New", href: "#new", current: true },
  { label: "Women", href: "#women" },
  { label: "Men", href: "#men" },
  { label: "Home", href: "#home" },
  { label: "Sale", href: "#sale" },
  { label: "Journal", href: "#journal" },
];

const CATEGORIES = [
  { label: "Outerwear", count: "128 items", img: "https://images.unsplash.com/photo-1551488831-00ddcb6c6bd3?auto=format&fit=crop&w=800&q=70" },
  { label: "Knitwear", count: "84 items", img: "https://images.unsplash.com/photo-1576566588028-4147f3842f27?auto=format&fit=crop&w=800&q=70" },
  { label: "Footwear", count: "212 items", img: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=800&q=70" },
  { label: "Accessories", count: "96 items", img: "https://images.unsplash.com/photo-1591561954557-26941169b49e?auto=format&fit=crop&w=800&q=70" },
];

const PRODUCTS = {
  "Bestsellers": [
    { id: "p1", name: "Merino Crew Sweater", category: "Knitwear", price: 148, img: "https://images.unsplash.com/photo-1620799140408-edc6dcb6d633?auto=format&fit=crop&w=700&q=70", swatches: ["#1f1d1a","#c8b89a","#7d8c7a"], tag: "Bestseller" },
    { id: "p2", name: "Relaxed Linen Shirt", category: "Shirts", price: 98, img: "https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=700&q=70", swatches: ["#f1ece1","#a7c2c7","#1f1d1a"] },
    { id: "p3", name: "Italian Leather Loafer", category: "Footwear", price: 285, img: "https://images.unsplash.com/photo-1560769629-975ec94e6a86?auto=format&fit=crop&w=700&q=70", swatches: ["#3a2a1c","#1f1d1a"] },
    { id: "p4", name: "Wide-Leg Wool Trouser", category: "Bottoms", price: 198, was: 248, img: "https://images.unsplash.com/photo-1594633313593-bab3825d0caf?auto=format&fit=crop&w=700&q=70", swatches: ["#1f1d1a","#5b5a55"], tag: "Sale" },
  ],
  "New Arrivals": [
    { id: "p5", name: "Quilted Field Jacket", category: "Outerwear", price: 320, img: "https://images.unsplash.com/photo-1591047139829-d91aecb6caea?auto=format&fit=crop&w=700&q=70", swatches: ["#3a3833","#6b6862"], tag: "New" },
    { id: "p6", name: "Cashmere Beanie", category: "Accessories", price: 78, img: "https://images.unsplash.com/photo-1576871337632-b9aef4c17ab9?auto=format&fit=crop&w=700&q=70", swatches: ["#1f1d1a","#c8b89a","#b3361f"], tag: "New" },
    { id: "p7", name: "Cotton Twill Chore Coat", category: "Outerwear", price: 215, img: "https://images.unsplash.com/photo-1544022613-e87ca75a784a?auto=format&fit=crop&w=700&q=70", swatches: ["#7d8c7a","#1f1d1a"], tag: "New" },
    { id: "p8", name: "Suede Chelsea Boot", category: "Footwear", price: 245, img: "https://images.unsplash.com/photo-1605733513597-a8f8341084e6?auto=format&fit=crop&w=700&q=70", swatches: ["#3a2a1c"], tag: "New" },
  ],
  "Editor's Picks": [
    { id: "p9", name: "Silk Slip Dress", category: "Dresses", price: 245, img: "https://images.unsplash.com/photo-1539109136881-3be0616acf4b?auto=format&fit=crop&w=700&q=70", swatches: ["#1f1d1a","#a7c2c7"] },
    { id: "p10", name: "Structured Tote Bag", category: "Accessories", price: 320, img: "https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=700&q=70", swatches: ["#3a2a1c","#1f1d1a"] },
    { id: "p11", name: "Heavy-Knit Cardigan", category: "Knitwear", price: 175, was: 225, img: "https://images.unsplash.com/photo-1620012253295-c15cc3e65df4?auto=format&fit=crop&w=700&q=70", swatches: ["#c8b89a","#1f1d1a"], tag: "Sale" },
    { id: "p12", name: "Ribbed Tank Top", category: "Tops", price: 48, img: "https://images.unsplash.com/photo-1581655353564-df123a1eb820?auto=format&fit=crop&w=700&q=70", swatches: ["#fafaf7","#1f1d1a","#7d8c7a"] },
  ],
};

const ARTICLES = [
  { tag: "Style Guide", title: "How to layer for the in-between season", excerpt: "Five looks that bridge late summer and early fall, built around the pieces you already own.", img: "https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=900&q=70" },
  { tag: "Inside the Studio", title: "The making of our signature merino", excerpt: "From the highlands of New Zealand to a finished garment — a journey in transparency.", img: "https://images.unsplash.com/photo-1558769132-cb1aea458c5e?auto=format&fit=crop&w=900&q=70" },
  { tag: "Conversations", title: "Designer Mira Soto on quiet luxury", excerpt: "On craft, restraint, and why the best wardrobe is one you barely think about.", img: "https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=900&q=70" },
];

/* ============ Icons ============ */
const Icon = ({ name, ...rest }) => {
  const paths = {
    search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></>,
    user: <><circle cx="12" cy="8" r="4"/><path d="M4 21c1.5-4 5-6 8-6s6.5 2 8 6"/></>,
    bag: <><path d="M5 8h14l-1.2 11.3a2 2 0 0 1-2 1.7H8.2a2 2 0 0 1-2-1.7L5 8z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></>,
    heart: <path d="M12 20s-7-4.5-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.5-7 10-7 10z"/>,
    menu: <><path d="M4 7h16"/><path d="M4 12h16"/><path d="M4 17h16"/></>,
    close: <><path d="M6 6l12 12"/><path d="M18 6 6 18"/></>,
    truck: <><path d="M2 7h11v9H2zM13 10h5l3 3v3h-8z"/><circle cx="6" cy="18" r="2"/><circle cx="17" cy="18" r="2"/></>,
    return: <><path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v5h5"/></>,
    leaf: <><path d="M5 19c8 0 14-6 14-14-8 0-14 6-14 14z"/><path d="M5 19c2-4 5-7 9-9"/></>,
    lock: <><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></>,
    instagram: <><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor"/></>,
    twitter: <path d="M22 5.8c-.7.3-1.5.6-2.3.7a4 4 0 0 0 1.8-2.2 8 8 0 0 1-2.6 1A4 4 0 0 0 12 9c0 .3 0 .6.1.9A11.4 11.4 0 0 1 3.6 5.4a4 4 0 0 0 1.2 5.3 4 4 0 0 1-1.8-.5v.1a4 4 0 0 0 3.2 3.9c-.5.1-1 .2-1.5.1a4 4 0 0 0 3.7 2.8A8 8 0 0 1 2 18.6 11.4 11.4 0 0 0 8.2 20c7.4 0 11.4-6.1 11.4-11.4v-.5A8 8 0 0 0 22 5.8z"/>,
    pinterest: <><circle cx="12" cy="12" r="9"/><path d="M11 17c-.5-2 1-7 1-7M9.5 11.5c0-1.7 1.3-3 3-3s2.7 1 2.7 2.7-1 3.3-2.7 3.3-1.7-1-1.7-1"/></>,
  };
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" {...rest}>
      {paths[name]}
    </svg>
  );
};

/* ============ Components ============ */

function AnnouncementBar() {
  return (
    <div className="announcement" role="region" aria-label="Site announcements">
      Free carbon-neutral shipping on orders over <strong>$120</strong> · Now shipping worldwide
    </div>
  );
}

function Header({ cartCount }) {
  const [navOpen, setNavOpen] = useState(false);
  return (
    <header className="site-header">
      <div className="container header-row">
        <a href="#" className="brand" aria-label="Maren &amp; Co — home">
          Maren<span>&amp;Co</span>
        </a>

        <nav
          className={`primary-nav${navOpen ? " is-open" : ""}`}
          id="primary-nav"
          aria-label="Primary"
        >
          <ul>
            {NAV_ITEMS.map((item) => (
              <li key={item.label}>
                <a href={item.href} aria-current={item.current ? "page" : undefined}>
                  {item.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>

        <div className="header-actions">
          <button className="icon-btn menu-toggle" type="button"
            aria-expanded={navOpen}
            aria-controls="primary-nav"
            aria-label={navOpen ? "Close menu" : "Open menu"}
